private func apexReducedCurves()
    throws -> [CertifiedAnalyticAnalyticIntersectionCurve]
{
    let sphere = Surface3D.analytic(.sphere(
        center: .origin,
        radius: 1.0
    ))
    let cone = Surface3D.analytic(.cone(
        apex: Point3D(x: 1.0, y: 0.0, z: 0.0),
        axis: .unitZ,
        halfAngle: atan(0.5)
    ))
    return try DefaultSurfaceSurfaceIntersector().intersections(
        first: sphere,
        second: cone,
        tolerance: tolerance
    ).compactMap { intersection in
        guard case let .curve(result) = intersection,
              case let .analyticAnalytic(exact) = result.truth,
              case let .sphereCone(curve) = exact.definition,
              curve.componentKind == .apexReducedAngularInterval else {
            return nil
        }
        return exact
    }

func halfLinear(at angle: Double) -> Double {
    axialCenter + slope * (
        radialCosine * cos(angle) + radialSine * sin(angle)
    )

let inverseQuadraticCosine = 1.0 / (
    configuration.quadraticA * cos(configuration.cone.halfAngle)
)
if componentKind == .apexReducedAngularInterval {
    let scale = 2.0 * inverseQuadraticCosine
    return ScalarDifferential(
        value: halfLinear.value * scale,
        first: halfLinear.first * scale,
        second: halfLinear.second * scale,
        third: halfLinear.third * scale
    )

    coneSurface: Surface3D,
    tolerance: ModelingTolerance
) throws -> Configuration {
    try sphereSurface.validate(tolerance: tolerance)
    try coneSurface.validate(tolerance: tolerance)
    guard case let .sphere(sphere) = CanonicalAnalyticSurface(sphereSurface),
          case let .cone(coneCanonical) = CanonicalAnalyticSurface(coneSurface) else {
        throw KernelError(
            phase: .geometry,
            code: .invalidInput,
            tolerance: tolerance,
            message: "A certified sphere-cone curve requires exact sphere and cone surfaces."
        )
    }
    let cone = try canonicalCone(coneCanonical, tolerance: tolerance)
    let centerOffset = sphere.center - cone.apex
    let axialCenter = centerOffset.dot(cone.axis)
    let radialCenter = centerOffset - cone.axis * axialCenter
    let zeroPoint = try cone.surface.point(
        u: 0.0,
        v: 1.0,
        tolerance: tolerance
    )
    let quarterPoint = try cone.surface.point(
        u: Double.pi * 0.5,
        v: 1.0,
        tolerance: tolerance
    )
    let axialStep = cone.axis * cos(cone.halfAngle)
    let sine = sin(cone.halfAngle)
    let zeroRadial = (zeroPoint - cone.apex - axialStep) / sine
    let quarterRadial = (quarterPoint - cone.apex - axialStep) / sine
    let slope = tan(cone.halfAngle)
    return Configuration(
        sphere: sphere,
        cone: cone,
        axialCenter: axialCenter,
        radialCosine: radialCenter.dot(zeroRadial),
        radialSine: radialCenter.dot(quarterRadial),
        quadraticA: 1.0 + slope * slope,
        quadraticC: centerOffset.dot(centerOffset)
            - sphere.radius * sphere.radius
    )

case let .cone(apex, axis, halfAngle):
    let basis = try analyticOrthonormalBasis(axis, tolerance: tolerance)
    let radial = basis.u * CanonicalSphereAngularPhase.candidate(at: u, cosine: true) + basis.v * CanonicalSphereAngularPhase.candidate(at: u, cosine: false)
    return apex + axis * (v * cos(halfAngle)) + radial * (v * sin(halfAngle))

package static func canonicalValue(at label: Double, cosine: Bool) -> Double? {
    if label == 0 || label == 2 * Double.pi || label == -2 * Double.pi {
        return cosine ? 1 : 0
    }
    if label == Double.pi || label == -Double.pi { return cosine ? -1 : 0 }
    if label == Double.pi * 0.5 { return cosine ? 0 : 1 }
    if label == -Double.pi * 0.5 { return cosine ? 0 : -1 }
    if label == Double.pi * 1.5 { return cosine ? 0 : -1 }
    if label == -Double.pi * 1.5 { return cosine ? 0 : 1 }
    return nil

if label.value.lower == label.value.upper,
   let sine = canonicalValue(at: first, cosine: false),
   let cos = canonicalValue(at: first, cosine: true) {
    return SurfaceIntervalJet.applyingUnaryFunction(to: phase,
        value: .exact(cosine ? cos : sine),
        firstDerivative: .exact(cosine ? -sine : cos),
        secondDerivative: .exact(cosine ? -cos : -sine),
        thirdDerivative: .exact(cosine ? sine : -cos))

import CADCore

func analyticOrthonormalBasis(
    _ normal: Vector3D,
    tolerance: ModelingTolerance
) throws -> (u: Vector3D, v: Vector3D) {
    let reference = abs(normal.x) < 0.8 ? Vector3D.unitX : Vector3D.unitY
    let u = try normal.cross(reference).normalized(tolerance: tolerance.distance)
    let v = try normal.cross(u).normalized(tolerance: tolerance.distance)
    return (u, v)
}

/// An interval whose arithmetic operations round away from the represented
/// real result. The model is defined by its stored `Double` values; use
/// `exact(_:)` for those inputs and `init(_:)` only when enclosing a value
/// produced outside this arithmetic boundary.
package struct OutwardScalarInterval: Sendable {
    package let lower: Double
    package let upper: Double

    package init(_ value: Double) {
        lower = value.nextDown
        upper = value.nextUp
    }

    package init(lower: Double, upper: Double) {
        self.lower = lower
        self.upper = upper
    }

    package static func exact(_ value: Double) -> OutwardScalarInterval {
        OutwardScalarInterval(lower: value, upper: value)
    }

    package static func enclosing(_ values: [Double]) -> OutwardScalarInterval {
        OutwardScalarInterval(
            lower: (values.min() ?? -.infinity).nextDown,
            upper: (values.max() ?? .infinity).nextUp
        )
    }

    package static func enclosing(
        _ values: [OutwardScalarInterval]
    ) -> OutwardScalarInterval {
        OutwardScalarInterval(
            lower: values.map({ $0.lower }).min() ?? -.infinity,
            upper: values.map({ $0.upper }).max() ?? .infinity
        )
    }

    package static func + (
        lhs: OutwardScalarInterval,
        rhs: OutwardScalarInterval
    ) -> OutwardScalarInterval {
        OutwardScalarInterval(
            lower: (lhs.lower + rhs.lower).nextDown,
            upper: (lhs.upper + rhs.upper).nextUp
        )
    }

    package static func - (
        lhs: OutwardScalarInterval,
        rhs: OutwardScalarInterval
    ) -> OutwardScalarInterval {
        OutwardScalarInterval(
            lower: (lhs.lower - rhs.upper).nextDown,
            upper: (lhs.upper - rhs.lower).nextUp
        )
    }

    package static func * (
        lhs: OutwardScalarInterval,
        rhs: OutwardScalarInterval
    ) -> OutwardScalarInterval {
        let p00 = lhs.lower * rhs.lower
        let p01 = lhs.lower * rhs.upper
        let p10 = lhs.upper * rhs.lower
        let p11 = lhs.upper * rhs.upper
        // Preserve Sequence's ordered comparison, including signed zero and NaN.
        var minimum = p00
        var maximum = p00
        if p01 < minimum { minimum = p01 }
        if p01 > maximum { maximum = p01 }
        if p10 < minimum { minimum = p10 }
        if p10 > maximum { maximum = p10 }
        if p11 < minimum { minimum = p11 }
        if p11 > maximum { maximum = p11 }
        return OutwardScalarInterval(
            lower: minimum.nextDown,
            upper: maximum.nextUp
        )
    }

    package static prefix func - (
        value: OutwardScalarInterval
    ) -> OutwardScalarInterval {
        OutwardScalarInterval(
            lower: (-value.upper).nextDown,
            upper: (-value.lower).nextUp
        )
    }

    package func divided(
        by denominator: OutwardScalarInterval
    ) -> OutwardScalarInterval? {
        guard isFinite, denominator.isFinite, denominator.excludesZero,
              lower <= upper, denominator.lower <= denominator.upper else { return nil }
        let q00 = lower / denominator.lower, q01 = lower / denominator.upper
        let q10 = upper / denominator.lower, q11 = upper / denominator.upper
        guard !q00.isNaN, !q01.isNaN, !q10.isNaN, !q11.isNaN else { return nil }
        return .init(lower: min(q00, q01, q10, q11).nextDown,
            upper: max(q00, q01, q10, q11).nextUp)
    }

    package func intersection(
        with other: OutwardScalarInterval
    ) -> OutwardScalarInterval? {
        let intersectionLower = max(lower, other.lower)
        let intersectionUpper = min(upper, other.upper)
        guard intersectionLower <= intersectionUpper else { return nil }
        return OutwardScalarInterval(
            lower: intersectionLower,
            upper: intersectionUpper
        )
    }

    package func union(
        _ other: OutwardScalarInterval
    ) -> OutwardScalarInterval {
        OutwardScalarInterval(
            lower: min(lower, other.lower),
            upper: max(upper, other.upper)
        )
    }

    package func contains(_ value: Double) -> Bool {
        lower <= value && value <= upper
    }

    package func intersects(_ other: OutwardScalarInterval) -> Bool {
        lower <= other.upper && other.lower <= upper
    }

    package func isStrictlyInside(_ other: OutwardScalarInterval) -> Bool {
        lower > other.lower && upper < other.upper
    }

    package var width: Double {
        (upper - lower).nextUp
    }

    package var isFinite: Bool {
        lower.isFinite && upper.isFinite
    }

    package var excludesZero: Bool {
        lower > 0.0 || upper < 0.0
    }

    package var sign: Int? {
        if lower > 0.0 { return 1 }
        if upper < 0.0 { return -1 }
        return nil
    }

    package var midpoint: Double {
        if lower < 0, upper > 0 { return lower * 0.5 + upper * 0.5 }
        return lower + (upper - lower) * 0.5
    }

    package var absoluteLowerBound: Double {
        if lower > 0.0 {
            return lower
        }
        if upper < 0.0 {
            return -upper
        }
        return 0.0
    }

    package var absoluteUpperBound: Double {
        max(abs(lower), abs(upper))
    }
}
